<?php $title="Attendance Report";require "../includes/header.php";$from=$_GET['from']??date('Y-m-01');$to=$_GET['to']??date('Y-m-d');$q=trim($_GET['q']??'');$status=$_GET['status']??'';$sql="SELECT s.roll,s.name,d.name dept,COUNT(a.id) total,SUM(a.status='Present') present,SUM(a.status='Absent') absent FROM students s LEFT JOIN departments d ON d.id=s.department_id LEFT JOIN attendance a ON a.student_id=s.id AND a.attendance_date BETWEEN ? AND ? WHERE 1";$p=[$from,$to];if($q){$sql.=" AND (s.name LIKE ? OR s.roll LIKE ?)";$p[]="%$q%";$p[]="%$q%";}$sql.=" GROUP BY s.id ORDER BY s.roll";$st=$pdo->prepare($sql);$st->execute($p);$rows=$st->fetchAll();?><div class="d-flex justify-content-between mb-3"><h2>Attendance Report</h2><button class="btn btn-outline-dark" onclick="window.print()">Print</button></div><form class="card p-3 mb-3 row g-2"><div class="col-md-3"><label>From</label><input type="date" name="from" value="<?=$from?>" class="form-control"></div><div class="col-md-3"><label>To</label><input type="date" name="to" value="<?=$to?>" class="form-control"></div><div class="col-md-4"><label>Student/Roll</label><input name="q" value="<?=htmlspecialchars($q)?>" class="form-control"></div><div class="col-md-2 align-self-end"><button class="btn btn-primary w-100">Generate</button></div></form><div class="card p-3 table-responsive"><table class="table"><thead><tr><th>Roll</th><th>Name</th><th>Department</th><th>Present</th><th>Absent</th><th>Total</th><th>Percentage</th></tr></thead><tbody><?php foreach($rows as $r):$pct=$r['total']?round($r['present']/$r['total']*100,1):0;?><tr><td><?=$r['roll']?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=htmlspecialchars($r['dept']??'-')?></td><td><span class="badge bg-success"><?=$r['present']??0?></span></td><td><span class="badge bg-danger"><?=$r['absent']??0?></span></td><td><?=$r['total']?></td><td><div class="progress"><div class="progress-bar" style="width:<?=$pct?>%"></div></div><?=$pct?>%</td></tr><?php endforeach;?></tbody></table></div><?php require "../includes/footer.php";?>